from pathlib import Path
root=Path(__file__).resolve().parents[4]
out=root/'design/south-africa-2010/assets/r1'
def svg(stem):return (out/'svg'/f'{stem}.svg').read_text()
header='<div class="phone-header"><h3>GIOCATORI</h3><div class="sweep">'+svg('ribbon-header').replace('<svg ', '<svg preserveAspectRatio="none" ')+'</div><div class="assembly">'+svg('foosball-rod')+'</div></div>'
items=[('foosball-figure','The figure','One rigid tabletop player.','figure'),('foosball-rod','Mounted on the rod','The header composition, with separate figure and rod layers.','rod'),('football','The football','A compact mark with a clear outer ring and panel pattern.','ball')]
cards=''.join(f'<article class="mark"><div class="art art-{cl}">{svg(stem)}</div><h3>{title}</h3><p>{desc}</p><a href="svg/{stem}.svg" download>Download SVG</a></article>' for stem,title,desc,cl in items)
sizes=''.join('<div class="size"><span>'+str(size)+' px</span><div style="height:'+str(size)+'px">'+svg('foosball-figure')+svg('football')+'</div></div>' for size in [24,48,96])
