for key,val in [('CARDS',cards),('HEADER_RIBBON',svg('ribbon-header')),('CORNER_RIBBON',svg('ribbon-corner')),('HEADER',header),('SIZES',sizes),('MOUNTED',svg('foosball-rod')),('BALL',svg('football'))]:page=page.replace(key,val)
# Repeated inline art receives unique IDs in the gallery; the downloaded masters retain stable layer names.
import re
count=0
def prefix(m):
 global count
 count+=1
 return re.sub(r'id="([^"]+)"',lambda x:f'id="preview-{count}-{x.group(1)}"',m.group())
page=re.sub(r'<svg\b[\s\S]*?</svg>',prefix,page)
import json
if json.loads((out/'manifest.json').read_text()).get('approval') == 'approved':
 page=page.replace('Artwork for your approval','Approved artwork').replace('Revision 1 · Pending approval','Revision 1 · Artwork approved')
(out/'review.html').write_text(page)
